CREATE FUNCTION [dbo].[listsalary_end_main](@Forms___F_MENU_BIM___MMO [int], @Forms___Baseknow___HSAY [int], @Forms___Baseknow___HJAZ [int], @Forms___Baseknow___HNAH [int], @Forms___Baseknow___HCON [int], @Forms___Baseknow___HKHA [int], @Forms___Baseknow___YEA [smallint],@Forms___Baseknow___HTAHOL [INT]) RETURNS TABLE AS RETURN ( SELECT dbo.PERSONEL.CODE, dbo.PERSONEL.PNAME, dbo.PERSONEL.PFAMILY, dbo.PERSONEL.PNAME + ' ' + dbo.PERSONEL.PFAMILY AS PNPF, dbo.PERSONEL.KHNOWNUM, dbo.PERSONEL.FATHER, dbo.PERSONEL.BIMEH_NUM, dbo.PERSONEL.JOB, dbo.PERSONEL.SEX, CASE WHEN dbo.Umonth(dbo.PERSONEL.WSDATE) = @Forms___F_MENU_BIM___MMO THEN dbo.PERSONEL.WSDATE ELSE NULL END AS WSDAT, dbo.PERSONEL.WEDATE, dbo.WORKING.WDATE, dbo.WORKING.DAYS, dbo.WORKING.EZAFAH, dbo.WORKING.PADASH, dbo.WORKING.KASR_VAM,dbo.Umonth(dbo.WORKING.WDATE) AS MM, dbo.PERSONEL.DSW_IDPLC, dbo.PERSONEL.DSW_NAT, dbo.PERSONEL.DSW_BDATE, dbo.PHOKM.HONUM, MAX(dbo.PHOKM.HDATE) AS MaxOfHDATE, dbo.PHOKM.SALARY_DAYLY, dbo.PHOKM.SALARY_DAYLYB, dbo.PHOKM.HOME, dbo.PHOKM.CHILDREN, dbo.PHOKM.CONDITIONS, dbo.PHOKM.haghtahol, dbo.PHOKM.BON, dbo.PHOKM.JAZB, dbo.PHOKM.SAYER, dbo.PERSONEL.TAB56, (CASE WHEN @Forms___Baseknow___HSAY = -1 THEN dbo.PHOKM.SAYER ELSE 0 END + CASE WHEN @Forms___Baseknow___HJAZ = -1 THEN dbo.PHOKM.JAZB ELSE 0 END + CASE WHEN @Forms___Baseknow___HNAH = -1 THEN dbo.PHOKM.BON ELSE 0 END + CASE WHEN @Forms___Baseknow___HCON = -1 THEN dbo.PHOKM.CONDITIONS ELSE 0 END + CASE WHEN @Forms___Baseknow___HTAHOL = -1 THEN dbo.PHOKM.HAGHTAHOL ELSE 0 END) * dbo.WORKING.DAYS + CASE WHEN @Forms___Baseknow___HKHA = -1 THEN dbo.PHOKM.HOME ELSE 0 END AS MAZMASH,(dbo.PHOKM.SAYER + dbo.PHOKM.JAZB + dbo.PHOKM.BON + dbo.PHOKM.CONDITIONS) * dbo.WORKING.DAYS + dbo.PHOKM.HOME + dbo.PHOKM.CHILDREN AS MAZYA, dbo.WORKING.TOLID, dbo.WORKING.DAYSB, dbo.WORKING.KASRM, dbo.WORKING.ECOL1, dbo.WORKING.ECOL2, dbo.WORKING.ECOL3, dbo.WORKING.KCOL1, dbo.WORKING.ECOL4 FROM dbo.PERSONEL INNER JOIN dbo.WORKING ON dbo.PERSONEL.CODE = dbo.WORKING.PCODE INNER JOIN dbo.PHOKM ON dbo.PERSONEL.CODE = dbo.PHOKM.CODE INNER JOIN dbo.LASTHOK2(@Forms___F_MENU_BIM___MMO, @Forms___Baseknow___YEA) LASTHOK2 ON dbo.PHOKM.HONUM = LASTHOK2.MaxOfHONUM AND dbo.PHOKM.CODE = LASTHOK2.CODE GROUP BY dbo.PERSONEL.CODE, dbo.PERSONEL.PNAME, dbo.PERSONEL.PFAMILY, dbo.PERSONEL.PNAME + ' ' + dbo.PERSONEL.PFAMILY, dbo.PERSONEL.KHNOWNUM, dbo.PERSONEL.FATHER, dbo.PERSONEL.BIMEH_NUM, dbo.PERSONEL.JOB, dbo.PERSONEL.SEX, CASE WHEN dbo.Umonth(dbo.PERSONEL.WSDATE) = @Forms___F_MENU_BIM___MMO THEN dbo.PERSONEL.WSDATE ELSE NULL END, dbo.PERSONEL.WEDATE,dbo.WORKING.WDATE, dbo.WORKING.DAYS, dbo.WORKING.EZAFAH, dbo.WORKING.PADASH, dbo.WORKING.KASR_VAM, dbo.Umonth(dbo.WORKING.WDATE), dbo.PERSONEL.DSW_IDPLC, dbo.PERSONEL.DSW_NAT, dbo.PERSONEL.DSW_BDATE, dbo.PHOKM.HONUM, dbo.PHOKM.SALARY_DAYLY, dbo.PHOKM.SALARY_DAYLYB, dbo.PHOKM.HOME, dbo.PHOKM.CHILDREN, dbo.PHOKM.CONDITIONS, dbo.PHOKM.haghtahol, dbo.PHOKM.BON, dbo.PHOKM.JAZB, dbo.PHOKM.SAYER, dbo.PERSONEL.TAB56, (CASE WHEN @Forms___Baseknow___HSAY = -1 THEN dbo.PHOKM.SAYER ELSE 0 END + CASE WHEN @Forms___Baseknow___HJAZ = -1 THEN dbo.PHOKM.JAZB ELSE 0 END + CASE WHEN @Forms___Baseknow___HNAH = -1 THEN dbo.PHOKM.BON ELSE 0 END + CASE WHEN @Forms___Baseknow___HCON = -1 THEN dbo.PHOKM.CONDITIONS ELSE 0 END + CASE WHEN @Forms___Baseknow___HTAHOL = -1 THEN dbo.PHOKM.HAGHTAHOL ELSE 0 END) * dbo.WORKING.DAYS + CASE WHEN @Forms___Baseknow___HKHA = -1 THEN dbo.PHOKM.HOME ELSE 0 END,(dbo.PHOKM.SAYER + dbo.PHOKM.JAZB + dbo.PHOKM.BON + dbo.PHOKM.CONDITIONS) * dbo.WORKING.DAYS + dbo.PHOKM.HOME + dbo.PHOKM.CHILDREN, dbo.WORKING.TOLID, dbo.WORKING.DAYSB, dbo.WORKING.KASRM, dbo.WORKING.ECOL1, dbo.WORKING.ECOL2, dbo.WORKING.ECOL3, dbo.WORKING.KCOL1, dbo.WORKING.ECOL4 HAVING (MAX(dbo.PHOKM.HDATE) <= dbo.WORKING.WDATE) AND (dbo.Umonth(dbo.WORKING.WDATE) = @Forms___F_MENU_BIM___MMO) )
